// Generated by `just generate` from `src/plugins/claudetto/slices/statusline/adapters/option.ts`. Edit the source and run `just generate`.
// The `compaction` option of the plugin, for the context segment.
// Claude Code gives `CLAUDE_PLUGIN_OPTION_*` only to a command in the `hooks.json` of a plugin.
// The `statusLine` command is in `settings.json`, so it does not get them.
// So the command reads the value that Claude Code saved in `pluginConfigs` of the user settings,
// and the env var wins when it is set.

import path from "node:path";
import { COMPACTION_OPTION } from "../../../kernel/compaction.ts";
import { failureText } from "../../../kernel/node/hook-io.ts";
import { SETTINGS_FILE } from "../../../kernel/paths.ts";
import type { FileReader } from "../../../kernel/ports.ts";

/** The name of the env var that Claude Code gives to a plugin hook. */
const OPTION_ENV = `CLAUDE_PLUGIN_OPTION_${COMPACTION_OPTION.toUpperCase()}`;

/** The id of the plugin in `pluginConfigs` is `claudetto@<marketplace>`. */
const PLUGIN_PREFIX = "claudetto@";

/** The user settings file for `env` and `home`: `settings.json` in `CLAUDE_CONFIG_DIR`, or in `.claude` of the home folder. */
export const userSettingsFile = (
  env: Readonly<Record<string, string | undefined>>,
  home: string,
): string =>
  path.join(
    env["CLAUDE_CONFIG_DIR"] || path.join(home, ".claude"),
    SETTINGS_FILE,
  );

/** The value of the `compaction` option, or `undefined` when the env var and the settings file have none. The cause of a read failure goes to `onError`. */
export const readCompactionOption = async (
  env: Readonly<Record<string, string | undefined>>,
  home: string,
  files: FileReader,
  onError: (text: string) => void,
): Promise<string | undefined> => {
  const fromEnv = env[OPTION_ENV];
  if (fromEnv) return fromEnv;
  try {
    const text = await files.read(userSettingsFile(env, home));
    if (text === null) return undefined;
    const configs = (JSON.parse(text) as { pluginConfigs?: unknown } | null)
      ?.pluginConfigs;
    if (configs === null || typeof configs !== "object") return undefined;
    for (const [id, config] of Object.entries(configs)) {
      if (!id.startsWith(PLUGIN_PREFIX)) continue;
      const value = (config as { options?: Record<string, unknown> } | null)
        ?.options?.[COMPACTION_OPTION];
      if (typeof value === "string") return value;
    }
    return undefined;
  } catch (err) {
    onError(failureText(err));
    return undefined;
  }
};
